def is_snake_number(n):
    digits = [int(digit) for digit in str(n)]
    return digits[0] > max(digits[1:]) and len(set(digits)) == len(digits)

def count_snake_numbers(L, R):
    count = 0
    for num in range(L, R + 1):
        if is_snake_number(num):
            count += 1
    return count

L, R = map(int, input().split())
print(count_snake_numbers(L, R))

def min_insertions(S):
    # Check if the length of the string is even
    if len(S) % 2 != 0:
        return 1

    # Initialize variables
    count = 0
    odd_index = 1

    # Iterate through the string
    for char in S:
        if char == 'i':
            if odd_index % 2 != 0:
                count += 1
            odd_index += 1
        else:
            if odd_index % 2 == 0:
                count += 1
            odd_index += 1

    return count

# Example usage
input_str = "ioi"
print(min_insertions(input_str))  # Output: 1

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        total_sum = sum(nums)
        if total_sum % 2 != 0:
            return 0

        # Calculate the prefix sums
        prefix_sums = [0] * len(nums)
        prefix_sums[0] = nums[0]
        for i in range(1, len(nums)):
            prefix_sums[i] = prefix_sums[i-1] + nums[i]

        # Initialize the result counter
        result = 0

        # Iterate through the array to find partitions
        for i in range(len(nums) - 1):
            left_sum = prefix_sums[i]
            right_sum = total_sum - left_sum

            # Check if the difference between left and right sums is even
            if (left_sum + right_sum) % 2 == 0:
                result += 1

        return result

