class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counter = Counter(nums)
        ans = float('-inf')
        for num in sorted(counter.keys(), reverse=True):
            while counter[num] > 0:
                if len(nums) < k or nums[-k:] != [num]*k:
                    counter[num] -= 1
                    continue
                ans = max(ans, num)
                break
        return ans if ans != float('-inf') else -1

def find_palindrome(N):
    if N == 1:
        return "-"
    elif N == 2:
        return "--"
    else:
        if N % 2 == 1:
            return "-" * (N // 2) + "=" + "-" * ((N - 1) // 2)
        else:
            return "-" * (N // 2) + "=" + "-" * ((N - 2) // 2)

# Test the function with provided data points
print(find_palindrome(4))  # Output: -==-
print(find_palindrome(7))  # Output: ---=---

